#include <bits/stdc++.h>
using namespace std;

const int dx[4] = {0, 0, 1, -1};
const int dy[4] = {1, -1, 0, 0};

int H, W;
vector<string> grid;
vector<vector<bool>> visited;

void dfs(int x, int y) {
    visited[x][y] = true;
    for (int k = 0; k < 4; k++) {
        int nx = x + dx[k], ny = y + dy[k];
        if (nx >= 0 && nx < H && ny >= 0 && ny < W && !visited[nx][ny] && grid[nx][ny] == '#') {
            dfs(nx, ny);
        }
    }
}

int count_components() {
    visited.assign(H, vector<bool>(W, false));
    int cnt = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '#' && !visited[i][j]) {
                cnt++;
                dfs(i, j);
            }
        }
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> H >> W;
    grid.resize(H);
    for (int i = 0; i < H; i++) {
        cin >> grid[i];
    }

    int initial_components = count_components();
    if (initial_components != 1) {
        // If already more than one component, the maximum is the current count
        cout << initial_components << "\n";
        return 0;
    }

    int max_parts = 1; // at least itself

    // Try all possible straight lines
    // Lines are defined by two cells (r1,c1) and (r2,c2) with r2>r1 or (r2==r1 and c2>c1)
    // But we need to consider all lines that can cut through the grid.
    // A simpler approach: iterate over all pairs of boundary points or all possible slopes.
    // Since H,W <= 50, we can try all lines defined by two distinct points on the grid boundary.
    // The line splits the grid into two half-planes. We remove cells on one side and count components.

    // Collect all boundary points
    vector<pair<int,int>> boundary;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (i == 0 || i == H-1 || j == 0 || j == W-1) {
                boundary.push_back({i, j});
            }
        }
    }

    int B = boundary.size();
    for (int i = 0; i < B; i++) {
        for (int j = i+1; j < B; j++) {
            int x1 = boundary[i].first, y1 = boundary[i].second;
            int x2 = boundary[j].first, y2 = boundary[j].second;
            if (x1 == x2 && y1 == y2) continue;

            // Define line: ax + by + c = 0
            // Using cross product: (x2-x1)*(y-y1) - (y2-y1)*(x-x1) = 0
            int a = y2 - y1;
            int b = x1 - x2;
            int c = x2*y1 - x1*y2;

            // For each cell, determine side
            // side = a*x + b*y + c
            // We will remove cells with side > 0 (one half-plane)
            // Then count components of remaining '#'

            // Store original grid
            vector<string> original = grid;

            // Remove cells on one side
            for (int r = 0; r < H; r++) {
                for (int c2 = 0; c2 < W; c2++) {
                    int val = a * r + b * c2 + c;
                    if (val > 0) {
                        grid[r][c2] = '.';
                    }
                }
            }

            int comp = count_components();
            max_parts = max(max_parts, comp);

            // Restore grid
            grid = original;

            // Also try the other side
            for (int r = 0; r < H; r++) {
                for (int c2 = 0; c2 < W; c2++) {
                    int val = a * r + b * c2 + c;
                    if (val < 0) {
                        grid[r][c2] = '.';
                    }
                }
            }

            comp = count_components();
            max_parts = max(max_parts, comp);

            grid = original;
        }
    }

    cout << max_parts << "\n";
    return 0;
}

