    int n = pts.size();
    for(int a=0;a<n;a++) for(int b=a+1;b<n;b++) {
        long long ax=pts[a].first, ay=pts[a].second;
        long long bx=pts[b].first, by=pts[b].second;
        // line from a to b: (bx-ax)*(y-ay) - (by-ay)*(x-ax) = 0
        // for cell center (i+0.5, j+0.5): use *2 to avoid fractions
        // sign = (bx-ax)*(2j+1-2ay) - (by-ay)*(2i+1-2ax)
        long long dx2=bx-ax, dy2=by-ay;
        vector<vector<int>> side(H, vector<int>(W,0));
        for(int i=0;i<H;i++) for(int j=0;j<W;j++) {
            long long val = dx2*(2*j+1-2*ay) - dy2*(2*i+1-2*ax);
            side[i][j] = (val>0)?1:(val<0)?-1:0;
        }
        int tot = countComponents(side,1)+countComponents(side,-1);
        ans = max(ans, tot);
