#include <bits/stdc++.h>
using namespace std;

/*
We have a connected union of unit squares ('#').
For a line l, removing l splits the set into connected components of S \ l.
We want the maximum possible number of components.

Key fact:
For any line, each resulting component must touch the line, and around the line
the components appear in some order along the line. Thus the number of components
equals the number of connected "intersection groups" of the shape with the line.

For a polygonal union of axis-aligned unit squares, the number of such groups only
changes when the line passes through a boundary vertex or becomes parallel to a
boundary edge. Therefore it suffices to test lines determined by pairs of boundary
vertices, plus vertical and horizontal lines through boundary x/y coordinates.

We model each occupied cell as the closed unit square [x,x+1]x[y,y+1].
For a candidate line, we classify every occupied cell:
- entirely on positive side
- entirely on negative side
- intersected by the line
Then components of S \ l are exactly connected components among non-intersected
cells using 4-neighbor adjacency.

This brute force over all candidate lines is fine because the grid is small enough
for typical ICPC constraints of this problem (the classic solution uses the same
critical-line idea). We deduplicate normalized lines.
*/

struct Line {
    long long a, b, c; // ax + by + c = 0
    bool operator<(const Line& other) const {
        if (a != other.a) return a < other.a;
        if (b != other.b) return b < other.b;
        return c < other.c;
    }
};

static long long gcd3(long long a, long long b, long long c) {
    return std::gcd(std::gcd(std::llabs(a), std::llabs(b)), std::llabs(c));
}

static Line normalize(long long a, long long b, long long c) {
    long long g = gcd3(a, b, c);
    if (g) a /= g, b /= g, c /= g;
    if (a < 0 || (a == 0 && b < 0) || (a == 0 && b == 0 && c < 0)) {
        a = -a; b = -b; c = -c;
    }
    return {a, b, c};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> G(H);
    for (int i = 0; i < H; ++i) cin >> G[i];

    vector<pair<int,int>> cells;
    for (int y = 0; y < H; ++y) {
        for (int x = 0; x < W; ++x) {
            if (G[y][x] == '#') cells.push_back({x, y});
        }
    }

    // Boundary/grid vertices relevant to the union of occupied cells:
    // using all vertices of occupied squares is sufficient.
    vector<pair<int,int>> verts;
    verts.reserve(cells.size() * 4);
    for (auto [x, y] : cells) {
        verts.push_back({x, y});
        verts.push_back({x+1, y});
        verts.push_back({x, y+1});
        verts.push_back({x+1, y+1});
    }
    sort(verts.begin(), verts.end());
    verts.erase(unique(verts.begin(), verts.end()), verts.end());

    set<Line> cand;

    // Vertical / horizontal candidates through relevant coordinates.
    for (auto [x, y] : verts) {
        cand.insert(normalize(1, 0, -x)); // x = const
        cand.insert(normalize(0, 1, -y)); // y = const
    }

    // Lines through pairs of relevant vertices.
    int V = (int)verts.size();
    for (int i = 0; i < V; ++i) {
        auto [x1, y1] = verts[i];
        for (int j = i + 1; j < V; ++j) {
            auto [x2, y2] = verts[j];
            long long a = (long long)y1 - y2;
            long long b = (long long)x2 - x1;
            long long c = -(a * x1 + b * y1);
            cand.insert(normalize(a, b, c));
        }
    }

    int n = (int)cells.size();
    vector<vector<int>> id(H, vector<int>(W, -1));
    for (int i = 0; i < n; ++i) {
        auto [x, y] = cells[i];
        id[y][x] = i;
    }

    int ans = 1;

    vector<int> alive(n), vis(n);
    queue<int> q;

    for (const auto& L : cand) {
        // alive[i] = 1 iff the line does NOT intersect interior of cell i
        for (int i = 0; i < n; ++i) {
            auto [x, y] = cells[i];
            long long v1 = L.a * x + L.b * y + L.c;
            long long v2 = L.a * (x + 1) + L.b * y + L.c;
            long long v3 = L.a * x + L.b * (y + 1) + L.c;
            long long v4 = L.a * (x + 1) + L.b * (y + 1) + L.c;

            long long mn = min(min(v1, v2), min(v3, v4));
            long long mx = max(max(v1, v2), max(v3, v4));

            // If both signs appear strictly, line passes through interior.
            // If all on one side or only touches boundary, cell remains (possibly clipped),
            // but for connectivity after removing the line, a touched-only cell still belongs
            // entirely to one side except measure-zero boundary; it should remain.
            // Interior intersection iff mn < 0 && mx > 0.
            alive[i] = ! (mn < 0 && mx > 0);
            vis[i] = 0;
        }

        int comps = 0;
        for (int i = 0; i < n; ++i) {
            if (!alive[i] || vis[i]) continue;
            ++comps;
            vis[i] = 1;
            q.push(i);
            while (!q.empty()) {
                int cur = q.front(); q.pop();
                auto [x, y] = cells[cur];
                const int dx[4] = {1,-1,0,0};
                const int dy[4] = {0,0,1,-1};
                for (int d = 0; d < 4; ++d) {
                    int nx = x + dx[d], ny = y + dy[d];
                    if (0 <= nx && nx < W && 0 <= ny && ny < H && id[ny][nx] != -1) {
                        int ni = id[ny][nx];
                        if (alive[ni] && !vis[ni]) {
                            vis[ni] = 1;
                            q.push(ni);
                        }
                    }
                }
            }
        }
        ans = max(ans, comps);
    }

    cout << ans << '\n';
    return 0;
}

