public class Main {
    static int H, W;
    static char[][] garden;
    static boolean[][] visited;

    static int[] dx = {0, 0, -1, 1};
    static int[] dy = {-1, 1, 0, 0};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        H = sc.nextInt();
        W = sc.nextInt();
        sc.nextLine();
        garden = new char[H][W];
        for (int i = 0; i < H; i++) {
            garden[i] = sc.nextLine().toCharArray();
        }

        int maxParts = 1; // at least 1 part initially

        // Try cutting between rows (horizontal cut)
        for (int cutRow = 0; cutRow < H - 1; cutRow++) {
            visited = new boolean[H][W];
            int parts = 0;
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (garden[i][j] == '#' && !visited[i][j]) {
                        // If cutRow separates this component, count it
                        if (wouldBeSeparate(i, j, cutRow, true)) {
                            parts++;
                            dfs(i, j, cutRow, true);
                        }
                    }
                }
            }
            maxParts = Math.max(maxParts, parts);
        }

        // Try cutting between columns (vertical cut)
        for (int cutCol = 0; cutCol < W - 1; cutCol++) {
            visited = new boolean[H][W];
            int parts = 0;
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (garden[i][j] == '#' && !visited[i][j]) {
                        if (wouldBeSeparate(i, j, cutCol, false)) {
                            parts++;
                            dfs(i, j, cutCol, false);
                        }
                    }
                }
            }
            maxParts = Math.max(maxParts, parts);
        }

        System.out.println(maxParts);
    }

    // Check if a cell is on the side that should be counted based on cut
    static boolean wouldBeSeparate(int x, int y, int cut, boolean isHorizontal) {
        if (isHorizontal) {
            return x <= cut;
        } else {
            return y <= cut;
        }
    }

    static void dfs(int x, int y, int cut, boolean isHorizontal) {
        if (x < 0 || x >= H || y < 0 || y >= W) return;
        if (garden[x][y] != '#') return;
        if (visited[x][y]) return;
        // Don't cross the cut line
        if (isHorizontal && x > cut) return;
        if (!isHorizontal && y > cut) return;
        visited[x][y] = true;
        for (int d = 0; d < 4; d++) {
            dfs(x + dx[d], y + dy[d], cut, isHorizontal);
        }
    }
}

