        int ans = 1;
        List<long[]> lines = new ArrayList<>();
        // Enumerate all lines through pairs of grid corner points
        List<int[]> pts = new ArrayList<>();
        for (int x = 0; x <= W; x++)
            for (int y = 0; y <= H; y++)
                pts.add(new int[]{x, y});

        for (int i = 0; i < pts.size(); i++)
            for (int j = i+1; j < pts.size(); j++) {
                int x1=pts.get(i)[0], y1=pts.get(i)[1], x2=pts.get(j)[0], y2=pts.get(j)[1];
                long a=y2-y1, b=x1-x2, c=(long)(x2-x1)*y1-(long)(y2-y1)*x1;
                lines.add(new long[]{a,b,c});
            }

        for (long[] line : lines) {
            long a=line[0],b=line[1],c=line[2];
            int[][] side = new int[H][W];
            for (int r=0;r<H;r++) for (int col=0;col<W;col++) {
                // cell center: x=col+0.5, y=r+0.5, multiply by 2
                long val = a*(2*col+1)+b*(2*r+1)+2*c;
                side[r][col] = Long.signum(val);
            }
            ans = Math.max(ans, countComponents(side, 1) + countComponents(side, -1));
        }
        System.out.println(ans);
    }

    static int countComponents(int[][] side, int s) {
        boolean[][] vis = new boolean[H][W];
        int count = 0;
        int[] dx={0,0,1,-1}, dy={1,-1,0,0};
        for (int r=0;r<H;r++) for (int c=0;c<W;c++) {
            if (!vis[r][c] && grid[r][c]=='#' && side[r][c]==s) {
                count++;
                Queue<int[]> q = new LinkedList<>();
                q.add(new int[]{r,c}); vis[r][c]=true;
                while (!q.isEmpty()) {
                    int[] cur=q.poll();
                    for (int d=0;d<4;d++) {
                        int nr=cur[0]+dy[d], nc=cur[1]+dx[d];
                        if (nr>=0&&nr<H&&nc>=0&&nc<W&&!vis[nr][nc]&&grid[nr][nc]=='#'&&side[nr][nc]==s) {
                            vis[nr][nc]=true; q.add(new int[]{nr,nc});
                        }
                    }
                }
            }
        }
        return count;
    }
}

