public class Main {
    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
    }

    static final double EPS = 1e-9;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();
        char[][] g = new char[H][];
        List<Point> vertices = new ArrayList<>();

        for (int i = 0; i < H; i++) {
            g[i] = fs.next().toCharArray();
        }

        // Collect all boundary vertices of the union of # cells.
        // Each # cell is [x,x+1] x [y,y+1], with y increasing downward in input,
        // but geometry is unaffected by vertical flip, so we use row index directly.
        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                if (g[r][c] != '#') continue;

                // If an edge is on the boundary, add its two endpoints.
                // top
                if (r == 0 || g[r - 1][c] == '.') {
                    vertices.add(new Point(c, r));
                    vertices.add(new Point(c + 1, r));
                }
                // bottom
                if (r == H - 1 || g[r + 1][c] == '.') {
                    vertices.add(new Point(c, r + 1));
                    vertices.add(new Point(c + 1, r + 1));
                }
                // left
                if (c == 0 || g[r][c - 1] == '.') {
                    vertices.add(new Point(c, r));
                    vertices.add(new Point(c, r + 1));
                }
                // right
                if (c == W - 1 || g[r][c + 1] == '.') {
                    vertices.add(new Point(c + 1, r));
                    vertices.add(new Point(c + 1, r + 1));
                }
            }
        }

        // Deduplicate vertices.
        List<Point> pts = dedup(vertices);

        int n = pts.size();
        if (n <= 1) {
            System.out.println(1);
            return;
        }

        int ans = 1;

        // For each pair of boundary vertices, consider the line through them.
        // For a polygonal connected figure, the number of pieces after cutting by a line
        // equals (# of connected components of intersection with the line) + 1.
        // For generic optimal lines, endpoints can be shifted to pass through boundary vertices,
        // so checking all such lines suffices.
        for (int i = 0; i < n; i++) {
            Point a = pts.get(i);
            for (int j = i + 1; j < n; j++) {
                Point b = pts.get(j);
                if (same(a, b)) continue;
                int pieces = countPieces(g, H, W, a, b);
                if (pieces > ans) ans = pieces;
            }
        }

        System.out.println(ans);
    }

    static int countPieces(char[][] g, int H, int W, Point a, Point b) {
        double dx = b.x - a.x;
        double dy = b.y - a.y;

        ArrayList<double[]> intervals = new ArrayList<>();

        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                if (g[r][c] != '#') continue;

                // Intersect line a + t*(dx,dy) with square [c,c+1] x [r,r+1].
                double tmin = -1e100, tmax = 1e100;

                // x constraint
                if (Math.abs(dx) < EPS) {
                    if (a.x < c - EPS || a.x > c + 1 + EPS) continue;
                } else {
                    double t1 = (c - a.x) / dx;
                    double t2 = (c + 1 - a.x) / dx;
                    if (t1 > t2) { double tmp = t1; t1 = t2; t2 = tmp; }
                    tmin = Math.max(tmin, t1);
                    tmax = Math.min(tmax, t2);
                }

                // y constraint
                if (Math.abs(dy) < EPS) {
                    if (a.y < r - EPS || a.y > r + 1 + EPS) continue;
                } else {
                    double t1 = (r - a.y) / dy;
                    double t2 = (r + 1 - a.y) / dy;
                    if (t1 > t2) { double tmp = t1; t1 = t2; t2 = tmp; }
                    tmin = Math.max(tmin, t1);
                    tmax = Math.min(tmax, t2);
                }

                if (tmin <= tmax + EPS) {
                    intervals.add(new double[]{tmin, tmax});
                }
            }
        }

        if (intervals.isEmpty()) return 1;

        intervals.sort((u, v) -> {
            if (Math.abs(u[0] - v[0]) > EPS) return Double.compare(u[0], v[0]);
            return Double.compare(u[1], v[1]);
        });

        int components = 0;
        double curL = intervals.get(0)[0];
        double curR = intervals.get(0)[1];
        components = 1;

        for (int i = 1; i < intervals.size(); i++) {
            double l = intervals.get(i)[0];
            double r = intervals.get(i)[1];
            if (l <= curR + EPS) {
                if (r > curR) curR = r;
            } else {
                components++;
                curL = l;
                curR = r;
            }
        }

        return components + 1;
    }

    static boolean same(Point a, Point b) {
        return Math.abs(a.x - b.x) < EPS && Math.abs(a.y - b.y) < EPS;
    }

    static List<Point> dedup(List<Point> list) {
        ArrayList<Point> res = new ArrayList<>();
        HashSet<Long> set = new HashSet<>();
        for (Point p : list) {
            long x = Math.round(p.x * 2); // all coordinates are integer or half not needed; here integer
            long y = Math.round(p.y * 2);
            long key = (x << 32) ^ (y & 0xffffffffL);
            if (set.add(key)) res.add(p);
        }
        return res;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

