typedef long long ll;

typedef struct {
    ll x1, y1, x2, y2;
} Seg;

static ll gcdll(ll a, ll b) {
    if (a < 0) a = -a;
    if (b < 0) b = -b;
    while (b) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll*)a;
    ll y = *(const ll*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    char **g = (char**)malloc(sizeof(char*) * H);
    for (int i = 0; i < H; i++) {
        g[i] = (char*)malloc(W + 5);
        scanf("%s", g[i]);
    }

    int maxSeg = 4 * H * W;
    Seg *segs = (Seg*)malloc(sizeof(Seg) * maxSeg);
    int segCnt = 0;

    /* Build boundary segments of the union of '#' cells.
       Coordinates are on the integer grid, each cell [x,x+1] x [y,y+1]. */
    for (int y = 0; y < H; y++) {
        for (int x = 0; x < W; x++) {
            if (g[y][x] != '#') continue;

            if (y == 0 || g[y-1][x] != '#') {
                segs[segCnt++] = (Seg){x, y, x+1, y};       // top
            }
            if (y == H-1 || g[y+1][x] != '#') {
                segs[segCnt++] = (Seg){x, y+1, x+1, y+1};   // bottom
            }
            if (x == 0 || g[y][x-1] != '#') {
                segs[segCnt++] = (Seg){x, y, x, y+1};       // left
            }
            if (x == W-1 || g[y][x+1] != '#') {
                segs[segCnt++] = (Seg){x+1, y, x+1, y+1};   // right
            }
        }
    }

    /* Candidate directions:
       For a line with normal vector (a,b), topology changes only when it becomes
       perpendicular to a segment joining two boundary vertices.
       So it suffices to test directions determined by differences of boundary vertices.
       Also include axis directions. */
    int maxV = 2 * segCnt + 10;
    ll *vx = (ll*)malloc(sizeof(ll) * maxV);
    ll *vy = (ll*)malloc(sizeof(ll) * maxV);
    int vcnt = 0;

    for (int i = 0; i < segCnt; i++) {
        vx[vcnt] = segs[i].x1; vy[vcnt] = segs[i].y1; vcnt++;
        vx[vcnt] = segs[i].x2; vy[vcnt] = segs[i].y2; vcnt++;
    }

    int maxDir = maxV * maxV + 10;
    ll *dirsA = (ll*)malloc(sizeof(ll) * maxDir);
    ll *dirsB = (ll*)malloc(sizeof(ll) * maxDir);
    int dirCnt = 0;

    dirsA[dirCnt] = 1; dirsB[dirCnt] = 0; dirCnt++;
    dirsA[dirCnt] = 0; dirsB[dirCnt] = 1; dirCnt++;

    for (int i = 0; i < vcnt; i++) {
        for (int j = i + 1; j < vcnt; j++) {
            ll dx = vx[j] - vx[i];
            ll dy = vy[j] - vy[i];
            if (dx == 0 && dy == 0) continue;
            ll a = -dy, b = dx;  // normal to segment direction
            ll g0 = gcdll(a, b);
            a /= g0; b /= g0;
            if (a < 0 || (a == 0 && b < 0)) {
                a = -a; b = -b;
            }
            dirsA[dirCnt] = a;
            dirsB[dirCnt] = b;
            dirCnt++;
        }
    }

    /* Deduplicate directions */
    ll *keys = (ll*)malloc(sizeof(ll) * dirCnt);
    for (int i = 0; i < dirCnt; i++) {
        keys[i] = (dirsA[i] << 32) ^ (dirsB[i] & 0xffffffffLL);
    }
    /* sort by (a,b) using keys is safe here since a,b are small enough */
    qsort(keys, dirCnt, sizeof(ll), cmp_ll);

    ll *uA = (ll*)malloc(sizeof(ll) * dirCnt);
    ll *uB = (ll*)malloc(sizeof(ll) * dirCnt);
    int uCnt = 0;
    for (int i = 0; i < dirCnt; i++) {
        if (i == 0 || keys[i] != keys[i-1]) {
            ll a = (keys[i] >> 32);
            ll b = (int)(keys[i] & 0xffffffffLL);
            uA[uCnt] = a;
            uB[uCnt] = b;
            uCnt++;
        }
    }

    int answer = 1;
    ll *vals = (ll*)malloc(sizeof(ll) * segCnt * 2);

    for (int di = 0; di < uCnt; di++) {
        ll a = uA[di], b = uB[di];
        int n = 0;

        for (int i = 0; i < segCnt; i++) {
            ll v1 = a * segs[i].x1 + b * segs[i].y1;
            ll v2 = a * segs[i].x2 + b * segs[i].y2;
            if (v1 == v2) {
                /* Segment parallel to the line family; it does not create events. */
                continue;
            }
            if (v1 > v2) {
                ll t = v1; v1 = v2; v2 = t;
            }
            vals[n++] = v1;
            vals[n++] = v2;
        }

        if (n == 0) continue;
        qsort(vals, n, sizeof(ll), cmp_ll);

        int cnt = 0;
        for (int i = 0; i < n; ) {
            ll x = vals[i];
            int c = 0;
            while (i < n && vals[i] == x) {
                c++;
                i++;
            }
            if (c & 1) cnt++;
        }

        /* For a generic offset in this direction, number of intersections with boundary
           equals cnt. Since the figure is connected, number of pieces is cnt/2 + 1. */
        int pieces = cnt / 2 + 1;
        if (pieces > answer) answer = pieces;
    }

    printf("%d\n", answer);

    return 0;
}

