        excluded = set()
        for c in range(W):
            if grid[row][c] == '#':
                excluded.add((row, c))
        if excluded:
            max_parts = max(max_parts, count_components(excluded))

    # Diagonal lines (r - c constant)
    for d in range(-(W-1), H):
        excluded = set()
        for r in range(H):
            c = r - d
            if 0 <= c < W and grid[r][c] == '#':
                excluded.add((r, c))
        if excluded:
            max_parts = max(max_parts, count_components(excluded))

    # Diagonal lines (r + c constant)
    for s in range(0, H+W-1):
        excluded = set()
        for r in range(H):
            c = s - r
            if 0 <= c < W and grid[r][c] == '#':
                excluded.add((r, c))
        if excluded:
            max_parts = max(max_parts, count_components(excluded))

    print(max_parts)

